import{_ as d,H as e,f as o,i as r}from"./chunks/framework.Cvt1eIE0.js";const b=JSON.parse('{"title":"03-키보드 단축키","description":"","frontmatter":{},"headers":[],"relativePath":"04-keyboard-shortcuts.md","filePath":"04-keyboard-shortcuts.md","lastUpdated":1778828590000}'),c={name:"04-keyboard-shortcuts.md"};function a(i,t,l,h,n,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_03-키보드-단축키" tabindex="-1">03-키보드 단축키 <a class="header-anchor" href="#_03-키보드-단축키" aria-label="Permalink to &quot;03-키보드 단축키&quot;">​</a></h1><p>Grok Build는 터미널 전체 화면 TUI로 동작하기 때문에, <strong>키보드 단축키</strong>를 잘 아는 것이 생산성에 큰 영향을 미칩니다.</p><p>이 문서는 단순히 단축키 목록을 나열하는 것이 아니라, <strong>처음 사용자도 이해하기 쉽게</strong> 어떤 상황에서 어떤 키를 쓰면 좋은지 중심으로 정리했습니다.</p><hr><h2 id="입력-모드-input-modes" tabindex="-1">입력 모드 (Input Modes) <a class="header-anchor" href="#입력-모드-input-modes" aria-label="Permalink to &quot;입력 모드 (Input Modes)&quot;">​</a></h2><p>Grok Build에는 두 가지 입력 모드가 있습니다.</p><h3 id="_1-simple-mode-기본-모드" tabindex="-1">1. Simple Mode (기본 모드) <a class="header-anchor" href="#_1-simple-mode-기본-모드" aria-label="Permalink to &quot;1. Simple Mode (기본 모드)&quot;">​</a></h3><ul><li><strong>기본으로 활성화</strong>되어 있습니다.</li><li>화살표 키(↑ ↓ ← →)로 스크롤백을 이동할 수 있습니다.</li><li><code>Shift + 화살표</code>로 턴(사용자 메시지 단위) 이동이 가능합니다.</li><li>아무 글자나 누르면 자동으로 프롬프트 입력란에 포커스가 갑니다.</li></ul><p><strong>추천 대상</strong>: 대부분의 사용자, 특히 처음 시작하는 사람</p><h3 id="_2-vim-mode-vim-스타일-모드" tabindex="-1">2. Vim Mode (Vim 스타일 모드) <a class="header-anchor" href="#_2-vim-mode-vim-스타일-모드" aria-label="Permalink to &quot;2. Vim Mode (Vim 스타일 모드)&quot;">​</a></h3><ul><li><code>config.toml</code>에서 <code>simple_mode = false</code>로 설정하면 활성화됩니다.</li><li>Vim 사용자에게 익숙한 <code>j</code> / <code>k</code> 키로 이동합니다.</li><li><code>h</code> / <code>l</code> 로 블록을 접고 펼칠 수 있습니다.</li><li>더 많은 단축키를 사용할 수 있지만, 처음에는 적응이 필요합니다.</li></ul><p><strong>추천 대상</strong>: Vim을 주로 사용하는 사람, 키보드 중심으로 빠르게 작업하고 싶은 사람</p><blockquote><p><strong>팁</strong>: 처음에는 Simple Mode로 충분히 사용해보고, 나중에 Vim Mode로 전환하는 것을 추천합니다.</p></blockquote><hr><h2 id="탐색-단축키-navigation" tabindex="-1">탐색 단축키 (Navigation) <a class="header-anchor" href="#탐색-단축키-navigation" aria-label="Permalink to &quot;탐색 단축키 (Navigation)&quot;">​</a></h2><p>스크롤백(위쪽 대화 영역)에 포커스가 있을 때 사용하는 이동 관련 단축키입니다.</p><table tabindex="0"><thead><tr><th>기능</th><th>Vim Mode</th><th>Simple Mode</th><th>설명</th></tr></thead><tbody><tr><td>다음 항목 선택</td><td><code>j</code></td><td><code>↓</code></td><td>아래로 이동</td></tr><tr><td>이전 항목 선택</td><td><code>k</code></td><td><code>↑</code></td><td>위로 이동</td></tr><tr><td>다음 턴으로 이동</td><td><code>Shift + L</code></td><td><code>Shift + →</code></td><td>다음 사용자 메시지로 점프</td></tr><tr><td>이전 턴으로 이동</td><td><code>Shift + H</code></td><td><code>Shift + ←</code></td><td>이전 사용자 메시지로 점프</td></tr><tr><td>맨 위로 이동</td><td><code>g</code></td><td>-</td><td>스크롤백 최상단</td></tr><tr><td>맨 아래로 이동</td><td><code>Shift + G</code></td><td>-</td><td>스크롤백 최하단</td></tr><tr><td>한 줄 위로 스크롤</td><td><code>Ctrl + K</code></td><td>-</td><td>선택은 유지한 채 화면 이동</td></tr><tr><td>한 줄 아래로 스크롤</td><td><code>Ctrl + J</code></td><td>-</td><td>선택은 유지한 채 화면 이동</td></tr><tr><td>한 페이지 위로</td><td><code>Page Up</code></td><td><code>Page Up</code></td><td>빠른 이동</td></tr><tr><td>한 페이지 아래로</td><td><code>Page Down</code></td><td><code>Page Down</code></td><td>빠른 이동</td></tr><tr><td>반 페이지 위로</td><td><code>Ctrl + U</code></td><td>-</td><td>중간 속도 이동</td></tr><tr><td>반 페이지 아래로</td><td><code>Ctrl + D</code></td><td>-</td><td>중간 속도 이동</td></tr></tbody></table><p><strong>실전 팁</strong>:</p><ul><li><code>Shift + H</code> / <code>Shift + L</code> 은 대화가 길어졌을 때 <strong>이전/다음 질문</strong>으로 빠르게 이동할 때 매우 유용합니다.</li><li><code>g</code> 와 <code>Shift + G</code> 는 긴 대화에서 특정 부분을 찾을 때 자주 사용됩니다.</li></ul><hr><h2 id="보기-제어-단축키-view" tabindex="-1">보기 제어 단축키 (View) <a class="header-anchor" href="#보기-제어-단축키-view" aria-label="Permalink to &quot;보기 제어 단축키 (View)&quot;">​</a></h2><p>스크롤백에 표시되는 내용의 형태를 제어하는 단축키입니다.</p><table tabindex="0"><thead><tr><th>기능</th><th>Vim Mode</th><th>Simple Mode</th><th>설명</th></tr></thead><tbody><tr><td>선택한 항목 접기</td><td><code>h</code></td><td><code>←</code></td><td>내용 숨기기</td></tr><tr><td>선택한 항목 펼치기</td><td><code>l</code></td><td><code>→</code></td><td>내용 보기</td></tr><tr><td>선택한 항목 접기/펼치기 토글</td><td><code>e</code></td><td>-</td><td>토글</td></tr><tr><td>모든 항목 접기/펼치기</td><td><code>Shift + E</code></td><td>-</td><td>전체 토글</td></tr><tr><td>Thinking Block 전체 토글</td><td><code>Ctrl + Shift + E</code></td><td>-</td><td>사고 과정 블록 전체</td></tr><tr><td>Turn View 모드 전환</td><td><code>Shift + T</code></td><td>-</td><td>전체 턴 보기 ↔ 단일 턴 보기</td></tr><tr><td>Raw Markdown 보기</td><td><code>r</code></td><td>-</td><td>원본 마크다운으로 보기</td></tr></tbody></table><h3 id="블록-내용-복사" tabindex="-1">블록 내용 복사 <a class="header-anchor" href="#블록-내용-복사" aria-label="Permalink to &quot;블록 내용 복사&quot;">​</a></h3><table tabindex="0"><thead><tr><th>기능</th><th>단축키</th><th>설명</th></tr></thead><tbody><tr><td>내용 복사</td><td><code>y</code></td><td>현재 선택된 블록 내용 복사</td></tr><tr><td>메타데이터 복사</td><td><code>Shift + Y</code></td><td>명령어, 파일 경로 등 메타데이터 복사</td></tr></tbody></table><p><strong>실전 팁</strong>:</p><ul><li><code>y</code> 키는 Grok이 실행한 shell 명령어나 생성된 코드를 빠르게 복사할 때 매우 유용합니다.</li><li><code>Shift + Y</code> 는 “이 명령어가 정확히 뭐였더라?” 싶을 때 메타데이터를 확인할 수 있습니다.</li></ul><hr><h2 id="prompt-입력란-단축키" tabindex="-1">Prompt 입력란 단축키 <a class="header-anchor" href="#prompt-입력란-단축키" aria-label="Permalink to &quot;Prompt 입력란 단축키&quot;">​</a></h2><p>프롬프트 입력란(하단 입력창)에 포커스가 있을 때 유용한 단축키입니다.</p><table tabindex="0"><thead><tr><th>기능</th><th>단축키</th><th>설명</th></tr></thead><tbody><tr><td>입력란 포커스 이동</td><td><code>Space</code>, <code>i</code>, <code>Tab</code></td><td>스크롤백 ↔ 프롬프트 전환</td></tr><tr><td>이전 입력 기록 불러오기</td><td><code>↑</code></td><td>최근에 입력한 메시지 불러오기</td></tr><tr><td>다음 입력 기록 불러오기</td><td><code>↓</code></td><td>다음 입력 기록으로 이동</td></tr><tr><td>입력 취소</td><td><code>Ctrl + C</code></td><td>현재 입력 취소</td></tr><tr><td>줄바꿈 (멀티라인)</td><td><code>Shift + Enter</code></td><td>긴 프롬프트 작성 시 사용</td></tr><tr><td>전체 입력 지우기</td><td><code>Ctrl + U</code></td><td>입력한 내용 모두 삭제</td></tr></tbody></table><p><strong>실전 팁</strong>:</p><ul><li><code>Space</code> 키는 스크롤백을 보고 있다가 바로 입력하고 싶을 때 가장 빠른 방법입니다.</li><li>긴 작업을 요청할 때는 <code>Shift + Enter</code>로 줄을 나눠서 작성하면 가독성이 좋습니다.</li></ul><hr><h2 id="전역-global-단축키" tabindex="-1">전역(Global) 단축키 <a class="header-anchor" href="#전역-global-단축키" aria-label="Permalink to &quot;전역(Global) 단축키&quot;">​</a></h2><p>스크롤백과 프롬프트 어디에서든 사용할 수 있는 중요한 단축키들입니다.</p><table tabindex="0"><thead><tr><th>기능</th><th>단축키</th><th>설명</th></tr></thead><tbody><tr><td>새 세션 시작</td><td><code>Ctrl + N</code></td><td>완전히 새로운 대화 시작</td></tr><tr><td>YOLO 모드 토글</td><td><code>Ctrl + O</code></td><td>자동 승인 모드 on/off</td></tr><tr><td>플러그인 관리 열기</td><td><code>Ctrl + L</code></td><td>Plugins, Marketplace, Hooks, MCP 관리</td></tr><tr><td>도움말 / 명령어 보기</td><td><code>Ctrl + ?</code> 또는 <code>?</code></td><td>사용 가능한 명령어 확인</td></tr><tr><td>세션 목록 보기</td><td><code>/load</code></td><td>이전 세션 불러오기</td></tr><tr><td>현재 세션 압축</td><td><code>/compact</code></td><td>대화 기록 압축 (토큰 절약)</td></tr><tr><td>모델 변경</td><td><code>/model</code></td><td>사용할 모델 변경</td></tr></tbody></table><p><strong>특히 중요한 단축키</strong></p><ul><li><code>Ctrl + N</code>: 새 프로젝트나 완전히 다른 주제를 시작할 때 자주 사용</li><li><code>Ctrl + O</code>: YOLO 모드를 빠르게 켜고 끄는 데 매우 유용</li><li><code>Ctrl + L</code>: Plugins, MCP, Hooks, Marketplace를 관리할 때 가장 많이 쓰는 단축키</li></ul><hr><h2 id="thinking-block-전용-단축키" tabindex="-1">Thinking Block 전용 단축키 <a class="header-anchor" href="#thinking-block-전용-단축키" aria-label="Permalink to &quot;Thinking Block 전용 단축키&quot;">​</a></h2><p>Grok이 생각하는 과정(Thinking Block)을 다루는 단축키입니다.</p><table tabindex="0"><thead><tr><th>기능</th><th>단축키</th><th>설명</th></tr></thead><tbody><tr><td>Thinking Block 접기/펼치기</td><td><code>h</code> / <code>l</code></td><td>선택된 Thinking Block 토글</td></tr><tr><td>모든 Thinking Block 토글</td><td><code>Ctrl + Shift + E</code></td><td>전체 사고 과정 한 번에 접거나 펼치기</td></tr><tr><td>Thinking Block 내용 복사</td><td><code>y</code> (선택 후)</td><td>내부 사고 과정 내용 복사</td></tr></tbody></table><p><strong>실전 팁</strong>:</p><ul><li>긴 대화에서는 <code>Ctrl + Shift + E</code>로 모든 Thinking Block을 접어두면 스크롤백이 훨씬 깔끔해집니다.</li><li>특정 Thinking Block만 자세히 보고 싶을 때는 <code>l</code> 키로 펼쳐서 확인하세요.</li></ul><hr><h2 id="실전에서-가장-많이-쓰이는-단축키-top-10" tabindex="-1">실전에서 가장 많이 쓰이는 단축키 Top 10 <a class="header-anchor" href="#실전에서-가장-많이-쓰이는-단축키-top-10" aria-label="Permalink to &quot;실전에서 가장 많이 쓰이는 단축키 Top 10&quot;">​</a></h2><p>처음 사용자라면 아래 단축키부터 익히는 것을 추천합니다.</p><table tabindex="0"><thead><tr><th>순위</th><th>단축키</th><th>용도</th></tr></thead><tbody><tr><td>1</td><td><code>Space</code></td><td>빠르게 입력란으로 이동</td></tr><tr><td>2</td><td><code>j</code> / <code>k</code> 또는 <code>↑</code>/<code>↓</code></td><td>스크롤백 이동</td></tr><tr><td>3</td><td><code>h</code> / <code>l</code></td><td>블록 접고 펼치기</td></tr><tr><td>4</td><td><code>y</code></td><td>내용 빠르게 복사</td></tr><tr><td>5</td><td><code>Ctrl + N</code></td><td>새 세션 시작</td></tr><tr><td>6</td><td><code>Shift + H</code> / <code>Shift + L</code></td><td>이전/다음 턴 이동</td></tr><tr><td>7</td><td><code>Ctrl + O</code></td><td>YOLO 모드 토글</td></tr><tr><td>8</td><td><code>Ctrl + L</code></td><td>플러그인/MCP 관리</td></tr><tr><td>9</td><td><code>g</code> / <code>Shift + G</code></td><td>스크롤백 맨 위/아래 이동</td></tr><tr><td>10</td><td><code>e</code></td><td>선택한 항목 접기/펼치기 토글</td></tr></tbody></table><h3 id="추천-조합" tabindex="-1">추천 조합 <a class="header-anchor" href="#추천-조합" aria-label="Permalink to &quot;추천 조합&quot;">​</a></h3><ul><li><strong>긴 대화 탐색</strong>: <code>Shift + H/L</code> + <code>j/k</code></li><li><strong>빠른 복사 후 질문</strong>: <code>y</code> → <code>Space</code> → 질문 입력</li><li><strong>YOLO로 빠르게 작업</strong>: <code>Ctrl + O</code> → 작업 → <code>Ctrl + O</code> (다시 끄기)</li></ul><hr><h2 id="전체-단축키-표-simple-mode-vs-vim-mode" tabindex="-1">전체 단축키 표 (Simple Mode vs Vim Mode) <a class="header-anchor" href="#전체-단축키-표-simple-mode-vs-vim-mode" aria-label="Permalink to &quot;전체 단축키 표 (Simple Mode vs Vim Mode)&quot;">​</a></h2><p>아래는 두 모드의 주요 단축키를 비교 정리한 표입니다.</p><h3 id="navigation-스크롤백-이동" tabindex="-1">Navigation (스크롤백 이동) <a class="header-anchor" href="#navigation-스크롤백-이동" aria-label="Permalink to &quot;Navigation (스크롤백 이동)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>기능</th><th>Vim Mode</th><th>Simple Mode</th></tr></thead><tbody><tr><td>다음 항목</td><td><code>j</code></td><td><code>↓</code></td></tr><tr><td>이전 항목</td><td><code>k</code></td><td><code>↑</code></td></tr><tr><td>다음 턴</td><td><code>Shift + L</code></td><td><code>Shift + →</code></td></tr><tr><td>이전 턴</td><td><code>Shift + H</code></td><td><code>Shift + ←</code></td></tr><tr><td>맨 위로</td><td><code>g</code></td><td>-</td></tr><tr><td>맨 아래로</td><td><code>Shift + G</code></td><td>-</td></tr><tr><td>한 줄 위 스크롤</td><td><code>Ctrl + K</code></td><td>-</td></tr><tr><td>한 줄 아래 스크롤</td><td><code>Ctrl + J</code></td><td>-</td></tr><tr><td>한 페이지 위</td><td><code>Page Up</code></td><td><code>Page Up</code></td></tr><tr><td>한 페이지 아래</td><td><code>Page Down</code></td><td><code>Page Down</code></td></tr><tr><td>반 페이지 위</td><td><code>Ctrl + U</code></td><td>-</td></tr><tr><td>반 페이지 아래</td><td><code>Ctrl + D</code></td><td>-</td></tr></tbody></table><h3 id="view-보기-제어" tabindex="-1">View (보기 제어) <a class="header-anchor" href="#view-보기-제어" aria-label="Permalink to &quot;View (보기 제어)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>기능</th><th>Vim Mode</th><th>Simple Mode</th></tr></thead><tbody><tr><td>선택 항목 접기</td><td><code>h</code></td><td><code>←</code></td></tr><tr><td>선택 항목 펼치기</td><td><code>l</code></td><td><code>→</code></td></tr><tr><td>선택 항목 토글</td><td><code>e</code></td><td>-</td></tr><tr><td>전체 접기/펼치기</td><td><code>Shift + E</code></td><td>-</td></tr><tr><td>Thinking Block 전체 토글</td><td><code>Ctrl + Shift + E</code></td><td>-</td></tr><tr><td>Turn View 전환</td><td><code>Shift + T</code></td><td>-</td></tr><tr><td>Raw Markdown 보기</td><td><code>r</code></td><td>-</td></tr></tbody></table><h3 id="content-actions-내용-다루기" tabindex="-1">Content Actions (내용 다루기) <a class="header-anchor" href="#content-actions-내용-다루기" aria-label="Permalink to &quot;Content Actions (내용 다루기)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>기능</th><th>단축키</th><th>설명</th></tr></thead><tbody><tr><td>내용 복사</td><td><code>y</code></td><td>블록 내용 복사</td></tr><tr><td>메타데이터 복사</td><td><code>Shift + Y</code></td><td>명령어/파일 경로 등 복사</td></tr><tr><td>Thinking Block 토글</td><td><code>h</code> / <code>l</code></td><td>사고 과정 접고 펼치기</td></tr></tbody></table><h3 id="prompt-입력란" tabindex="-1">Prompt (입력란) <a class="header-anchor" href="#prompt-입력란" aria-label="Permalink to &quot;Prompt (입력란)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>기능</th><th>단축키</th><th>설명</th></tr></thead><tbody><tr><td>입력란으로 이동</td><td><code>Space</code>, <code>i</code>, <code>Tab</code></td><td>스크롤백 ↔ 프롬프트</td></tr><tr><td>이전 입력 불러오기</td><td><code>↑</code></td><td>히스토리 위로</td></tr><tr><td>다음 입력 불러오기</td><td><code>↓</code></td><td>히스토리 아래로</td></tr><tr><td>입력 취소</td><td><code>Ctrl + C</code></td><td>현재 입력 취소</td></tr><tr><td>줄바꿈</td><td><code>Shift + Enter</code></td><td>멀티라인 입력</td></tr><tr><td>입력 전체 삭제</td><td><code>Ctrl + U</code></td><td>입력 내용 지우기</td></tr></tbody></table><h3 id="global-전역" tabindex="-1">Global (전역) <a class="header-anchor" href="#global-전역" aria-label="Permalink to &quot;Global (전역)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>기능</th><th>단축키</th><th>설명</th></tr></thead><tbody><tr><td>새 세션</td><td><code>Ctrl + N</code></td><td>새 대화 시작</td></tr><tr><td>YOLO 모드 토글</td><td><code>Ctrl + O</code></td><td>자동 승인 on/off</td></tr><tr><td>플러그인/훅/MCP 관리</td><td><code>Ctrl + L</code></td><td>관리 모달 열기</td></tr><tr><td>도움말</td><td><code>?</code> 또는 <code>Ctrl + ?</code></td><td>명령어 목록 보기</td></tr></tbody></table><hr><h2 id="vim-mode-사용자에게-유용한-고급-단축키" tabindex="-1">Vim Mode 사용자에게 유용한 고급 단축키 <a class="header-anchor" href="#vim-mode-사용자에게-유용한-고급-단축키" aria-label="Permalink to &quot;Vim Mode 사용자에게 유용한 고급 단축키&quot;">​</a></h2><p>Vim Mode를 사용하는 사람들을 위한 추가 팁:</p><ul><li><code>e</code> : 선택한 항목 fold 토글 (접고 펼치기)</li><li><code>Shift + E</code> : 전체 fold 토글 (모두 접거나 모두 펼치기)</li><li><code>r</code> : 선택한 블록을 Raw Markdown으로 보기 (디버깅이나 복사할 때 유용)</li><li><code>Shift + T</code> : All-turns view ↔ Single-turn view 전환 (긴 대화에서 유용)</li><li><code>Ctrl + Shift + E</code> : 모든 Thinking Block을 한 번에 접거나 펼치기</li></ul><p>Vim Mode는 처음엔 어색할 수 있지만, 익숙해지면 <strong>훨씬 빠르게</strong> 대화를 탐색할 수 있습니다.</p><hr><h2 id="자주-묻는-질문-faq" tabindex="-1">자주 묻는 질문 (FAQ) <a class="header-anchor" href="#자주-묻는-질문-faq" aria-label="Permalink to &quot;자주 묻는 질문 (FAQ)&quot;">​</a></h2><p><strong>Q. 단축키가 안 먹혀요.</strong></p><ul><li>스크롤백에 포커스가 있는지 확인하세요. (프롬프트에 포커스가 있으면 일부 단축키가 동작하지 않습니다.)</li><li><code>Space</code>를 눌러 스크롤백으로 포커스를 이동해보세요.</li></ul><p><strong>Q. Vim Mode가 이상해요.</strong></p><ul><li><code>simple_mode = false</code>로 설정했는지 확인하세요 (<code>~/.grok/config.toml</code>).</li><li>Vim Mode는 <code>j/k/h/l</code> 중심으로 동작합니다. 화살표 키는 Simple Mode에서만 자연스럽게 작동합니다.</li></ul><p><strong>Q. Thinking Block이 너무 많아서 정신없어요.</strong></p><ul><li><code>Ctrl + Shift + E</code>로 모든 Thinking Block을 접어두세요.</li><li>필요할 때만 <code>l</code> 키로 펼쳐서 확인하는 걸 추천합니다.</li></ul><p><strong>Q. 가장 추천하는 단축키 조합은?</strong></p><ul><li><code>Shift + H/L</code> (턴 이동) + <code>j/k</code> (세밀 이동) + <code>y</code> (복사) + <code>Space</code> (입력) 조합이 가장 많이 쓰입니다.</li></ul><hr><p><strong>03-키보드-단축키.md 끝</strong></p><p>여기까지 Grok Build TUI에서 사용할 수 있는 주요 키보드 단축키를 정리했습니다.</p><p><strong>Simple Mode</strong>로 충분히 시작하고, 익숙해지면 <strong>Vim Mode</strong>로 전환하는 걸 추천합니다.</p><p>자주 쓰는 단축키 몇 개만이라도 익혀두면, Grok Build 사용 경험이 확실히 빨라지고 편해집니다.</p><p>이 문서에서 다루지 않은 특수한 단축키가 필요하거나, Vim Mode에서 더 깊게 알고 싶다면 언제든 말씀해주세요.</p><hr><p><em>이 가이드는 실제 사용 경험을 바탕으로, 처음 사용자와 Vim 사용자 모두를 고려하여 작성되었습니다.</em></p><p>지금까지 Prompt 입력란, 전역 단축키, Thinking Block 단축키, 그리고 실전 추천 Top 10을 다루었습니다.</p><hr><ul><li>전체 단축키 표 (Simple Mode / Vim Mode 완전 정리)</li><li>Vim Mode 사용자에게 유용한 고급 단축키</li><li>자주 묻는 질문 정리 (예: &quot;이 단축키가 안 먹혀요&quot;)</li></ul><hr>',91)])])}const m=d(c,[["render",a]]);export{b as __pageData,m as default};
